// This module provides overflow/underflow-safe queue operations.
// The queue invariant (0 <= len <= cap) is maintained across
// all operations through formal pre/post-conditions.

// Enqueue: add element to queue (overflow prevention)
atom enqueue(len: i64, cap: i64)
requires: len >= 0 && cap > 0 && len < cap;
ensures: result == len + 1 && result <= cap;
body: {
    len + 1
};

// Dequeue: remove element from queue (underflow prevention)
atom dequeue(len: i64)
requires: len > 0;
ensures: result == len - 1 && result >= 0;
body: {
    len - 1
};

// Is empty: check if queue has no elements
atom is_empty(len: i64)
requires: len >= 0;
ensures: result >= 0 && result <= 1 && (len == 0 => result == 1) && (len > 0 => result == 0);
body: {
    if len == 0 { 1 } else { 0 }
};

// Is full: check if queue is at capacity
atom is_full(len: i64, cap: i64)
requires: len >= 0 && cap > 0 && len <= cap;
ensures: result >= 0 && result <= 1 && (len == cap => result == 1) && (len < cap => result == 0);
body: {
    if len == cap { 1 } else { 0 }
};
